import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Subcontractor operations & settlements","description":"","frontmatter":{},"headers":[],"relativePath":"plus/subcontractors.md","filePath":"plus/subcontractors.md"}'),o={name:"plus/subcontractors.md"};function i(s,e,c,l,p,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="subcontractor-operations-settlements" tabindex="-1">Subcontractor operations &amp; settlements <a class="header-anchor" href="#subcontractor-operations-settlements" aria-label="Permalink to &quot;Subcontractor operations &amp; settlements&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="assign-an-external-supplier" tabindex="-1">Assign an external supplier <a class="header-anchor" href="#assign-an-external-supplier" aria-label="Permalink to &quot;Assign an external supplier&quot;">​</a></h2><ol><li>Confirm the approved supplier relationship, company identity, contact and agreed commercial terms. An external supplier is distinct from an affiliate earning commission.</li><li>Create or review the subcontractor record in the authorized workspace. Select the reservation, correct journey leg and subcontractor; verify the agreed supplier amount.</li><li>Record the outsourcing assignment and review supplier acceptance, rejection or completion. Confirm the saved status and coordinate the relevant schedule. Do not assume an internal chauffeur assignment or the other return leg has changed.</li><li>Resolve conflicts and ensure the passenger-facing service remains correct before confirming any operational decision.</li></ol><h2 id="supplier-payment-and-profitability" tabindex="-1">Supplier payment and profitability <a class="header-anchor" href="#supplier-payment-and-profitability" aria-label="Permalink to &quot;Supplier payment and profitability&quot;">​</a></h2><p>Review outstanding supplier payables and the assignment record. Only authorized administrators can record settlements and reconciliation through the supported workflow. Enter the actual settlement amount and unique reference; verify remaining payable. Duplicate payout references and over-settlement are blocked. Recording a supplier settlement is not evidence that an external bank transfer has occurred.</p><p>Use profitability reporting to review recorded revenue and supplier costs. It is not a complete accounting statement; reconcile against approved financial records. No autonomous external supplier dispatch or payment is asserted.</p><p>See <a href="/plus/commercial-partners.html">Commercial partners</a> and <a href="/plus/payments-and-reconciliation.html">Payments and reconciliation</a>.</p>',8)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
